sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

	var getRequestType = g_form.getValue('u_request_type');

    if(getRequestType === 'hr'){
		g_form.clearOptions('u_what_needed');
		g_form.addOption('u_what_needed', 'hr_1', 'Human Resources 1');
		g_form.addOption('u_what_needed', 'hr_2', 'Human Resources 2');
		g_form.addOption('u_what_needed', 'other', 'Other');
    }else if(getRequestType === 'facilities'){
		g_form.clearOptions('u_what_needed');
		g_form.addOption('u_what_needed', 'facilities_1', 'Facilities 1');
		g_form.addOption('u_what_needed', 'facilities_2', 'Facilities 2');
		g_form.addOption('u_what_needed', 'other', 'Other');
    }else if(getRequestType === 'legal'){
		g_form.clearOptions('u_what_needed');
		g_form.addOption('u_what_needed', 'legal_1', 'Legal 1');
		g_form.addOption('u_what_needed', 'legal_2', 'Legal 2');
		g_form.addOption('u_what_needed', 'other', 'Other');
    }
}
